let lastSavedOwned=new Set(state.owned);function save(){try{state.ownedAt=state.ownedAt&&typeof state.ownedAt==='object'?state.ownedAt:{};for(const id of state.owned){if(!lastSavedOwned.has(id)&&!state.ownedAt[id])state.ownedAt[id]=Date.now()}localStorage.setItem(KEY,JSON.stringify(state));lastSavedOwned=new Set(state.owned)}catch(e){}}
